    /// Tables/charts/diagrams escalate to selective parse; plain text stays cheap.
    pub fn prefers_structured_parse(self) -> bool {
        matches!(
            self,
            Self::Table | Self::Chart | Self::Diagram | Self::Equation
        )
    }
